cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void scan_kernel(const half* input, half* output, int total_elements, int dim_size, int stride) {
    // Shared memory for block-level scan
    extern __shared__ half shared_data[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Process elements in chunks
    for (int base_offset = 0; base_offset < total_elements; base_offset += stride) {
        int offset = batch_idx * stride + tid;

        if (offset < total_elements && tid < dim_size) {
            shared_data[tid] = input[offset];
        }

        __syncthreads();

        // Up-sweep (reduce) phase
        for (int stride = 1; stride < dim_size; stride *= 2) {
            int index = (tid + 1) * stride * 2 - 1;
            if (index < dim_size) {
                shared_data[index] += shared_data[index - stride];
            }
            __syncthreads();
        }

        // Down-sweep phase
        if (tid == 0 && dim_size > 0) {
            shared_data[dim_size - 1] = 0;
        }
        __syncthreads();

        for (int stride = dim_size / 2; stride > 0; stride /= 2) {
            int index = (tid + 1) * stride * 2 - 1;
            if (index < dim_size) {
                half temp = shared_data[index];
                shared_data[index] += shared_data[index - stride];
                shared_data[index - stride] = temp;
            }
            __syncthreads();
        }

        // Write back results
        if (offset < total_elements && tid < dim_size) {
            output[offset] = shared_data[tid];
        }
        __syncthreads();
    }
}

__global__ void scan_kernel_simple(const half* input, half* output, int total_elements, int dim_size, int stride) {
    // Simple sequential scan for small arrays
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Each thread handles one element in the current batch
    int base_offset = batch_idx * stride;

    if (base_offset + tid < total_elements && tid < dim_size) {
        half sum = 0;
        for (int i = 0; i <= tid; i++) {
            sum += input[base_offset + i];
        }
        output[base_offset + tid] = sum;
    }
}

void launch_scan_kernel(const half* input, half* output, int total_elements, int dim_size, int stride) {
    int num_batches = total_elements / stride;
    int threads_per_block = 256;

    if (dim_size <= 128) {
        // Use simple kernel for small arrays
        dim3 grid_size(num_batches);
        dim3 block_size(threads_per_block);
        scan_kernel_simple<<<grid_size, block_size>>>(input, output, total_elements, dim_size, stride);
    } else {
        // Use shared memory based kernel for larger arrays
        dim3 grid_size(num_batches);
        dim3 block_size(min(dim_size, 1024));
        size_t shared_mem_size = min(dim_size, 1024) * sizeof(half);
        scan_kernel<<<grid_size, block_size, shared_mem_size>>>(input, output, total_elements, dim_size, stride);
    }
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="scan_kernel",
        cpp_sources="",
        cuda_sources=cuda_source,
        functions=["launch_scan_kernel"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, dim):
            super().__init__()
            self.dim = dim

        def forward(self, x):
            # Get input shape
            shape = x.shape
            total_elements = x.numel()

            # Calculate stride for the specified dimension
            stride = shape[self.dim]

            # Flatten to 2D for processing (batch_size, stride)
            if len(shape) > 2:
                batch_size = 1
                for i in range(len(shape)):
                    if i != self.dim:
                        batch_size *= shape[i]
                flattened = x.view(batch_size, stride)
            else:
                flattened = x

            # Allocate output
            output = torch.empty_like(flattened, dtype=torch.float16)

            # Launch kernel
            module.launch_scan_kernel(
                flattened.data_ptr(),
                output.data_ptr(),
                total_elements,
                stride,
                stride
            )

            # Reshape back to original shape
            if len(shape) > 2:
                result = output.view(shape)
            else:
                result = output

            return result

    return ModelNew

# Create the model class
ModelNew = compile_and_run()

# Test function
